            if (char === '*') {
                pos++;
                result *= parseFactor();
            } else if (char === '/') {
                pos++;
                const divisor = parseFactor();
                if (divisor === 0) {
                    throw new Error('Division by zero');
                }
                result /= divisor;
            } else {
                break;
            }
        }

        return result;
    }

    function parseFactor() {
        if (expr[pos] === '(') {
            pos++;
            const result = parseExpression();
            if (expr[pos] !== ')') {
                throw new Error('Missing closing parenthesis');
            }
            pos++;
            return result;
        } else if (expr[pos] === '-' && !isNaN(expr[pos + 1])) {
            pos++;
            return -parseFactor();
        } else {
            return parseNumber();
